const input = $input.first().json;

// Comprehensive Regex for Burmese Unicode & Zawgyi ranges
const burmeseRegex = /[\u1000-\u109F\uAA60-\uAA7F\uA9E0-\uA9FF]/;

// Future-proof recursive function to scan everything inside the JSON
function scanForBurmese(obj) {
  if (!obj) return false;

  // If it's a string, test it directly
  if (typeof obj === 'string') {
    return burmeseRegex.test(obj);
  }

  // If it's an array or object, dive deeper into its values
  if (typeof obj === 'object') {
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        if (scanForBurmese(obj[key])) {
          return true; // Stop immediately and return Yes if any Burmese is found
        }
      }
    }
  }

  return false;
}

return {
  ...input,
  containsBurmese: scanForBurmese(input) ? "Yes" : "No"
};

// 1. Safely extract the input data item regardless of the node's loop settings
let incomingItem;
try {
  // If running in "all items" mode
  const allData = this.getInputData();
  incomingItem = allData[0]?.json || $json;
} catch (e) {
  // Fallback for standard item context
  incomingItem = $json;
}

// 2. Fetch the text response generated by the AI agent
const agentOutput = incomingItem?.output || "";

// 3. Look back and pull your account and conversation IDs from GetSessionId
// Fixed: Using .first() to prevent the pairedItem error
const sessionIdData = $('GetSessionId').first().json;
const accountId = sessionIdData?.accountId || "";
const conversationId = sessionIdData?.conversationId || "";

// 4. Return everything packaged in the exact format n8n expects
return {
  accountId: accountId,
  conversationId: conversationId,
  output: agentOutput
};

const input = $input.first().json;
const body = input?.body || {};

let isIncomingCustomerMessage = false;

// 1. Event အမျိုးအစားကို စစ်ဆေးခြင်း
const isValidEvent = ["message_created", "conversation_updated"].includes(body.event);

if (isValidEvent) {

  // 2. Message Type ကို နေရာစုံကနေ ရှာဖွေစစ်ဆေးခြင်း
  const rootMessageType = body.message_type;
  const conversationMessageType = body.conversation?.messages?.[0]?.message_type;
  const directMessageType = body.messages?.[0]?.message_type;

  const isIncoming = rootMessageType === 0 || rootMessageType === "incoming" || 
                     conversationMessageType === 0 || conversationMessageType === "incoming" ||
                     directMessageType === 0 || directMessageType === "incoming";

  // 3. Sender Type ကို ရနိုင်သမျှ လမ်းကြောင်းအစုံကနေ လိုက်ရှာပြီး စာလုံးအသေးပြောင်းခြင်း
  let senderType = "";

  if (body.sender?.type) {
    senderType = body.sender.type;
  } else if (body.conversation?.messages?.[0]?.sender_type) {
    senderType = body.conversation.messages[0].sender_type;
  } else if (body.messages?.[0]?.sender_type) {
    senderType = body.messages[0].sender_type;
  } else if (body.conversation?.meta?.sender?.type) {
    senderType = body.conversation.meta.sender.type;
  }

  // စာလုံးအသေး ပြောင်းလဲခြင်း
  senderType = senderType ? senderType.toLowerCase() : "";

  // 4. အခြေအနေ ကိုက်ညီပါက True ဟု သတ်မှတ်မည်
  if (isIncoming && senderType === "contact") {
    isIncomingCustomerMessage = true;
  }
}

// ရလဒ်ကို ပို့ပေးမည်
return {
  ...input,
  isValidCustomerMessage: isIncomingCustomerMessage
};

